function kthSmallest(matrix, k) {
  const all = matrix.flat().sort((a, b) => a - b);   // every value, smallest first
  return all[k - 1];
}

int kthSmallest(int[][] matrix, int k) {
    int n = matrix.length;
    int[] all = new int[n * n];
    for (int r = 0; r < n; r++)
        for (int c = 0; c < n; c++) all[r * n + c] = matrix[r][c];
    Arrays.sort(all);                                    // every value, smallest first
    return all[k - 1];
}

int kthSmallest(vector<vector<int>>& matrix, int k) {
    vector<int> all;
    for (auto& row : matrix) all.insert(all.end(), row.begin(), row.end());
    sort(all.begin(), all.end());                        // every value, smallest first
    return all[k - 1];
}

function kthSmallest(matrix, k) {
  const n = matrix.length;
  const heap = new Heap((a, b) => a[0] - b[0]);      // [value, row, col]: the smallest front on top
  for (let r = 0; r < Math.min(n, k); r++) heap.push([matrix[r][0], r, 0]);   // each row's first value
  for (let i = 1; i < k; i++) {
    const [, r, c] = heap.pop();                     // the next smallest overall
    if (c + 1 < n) heap.push([matrix[r][c + 1], r, c + 1]);   // its row moves forward
  }
  return heap.peek()[0];
}

import heapq

def kth_smallest(matrix, k):
    n = len(matrix)
    heap = [(matrix[r][0], r, 0) for r in range(min(n, k))]   # each row's first value
    heapq.heapify(heap)
    for _ in range(k - 1):
        _, r, c = heapq.heappop(heap)                # the next smallest overall
        if c + 1 < n:
            heapq.heappush(heap, (matrix[r][c + 1], r, c + 1))   # its row moves forward
    return heap[0][0]

int kthSmallest(int[][] matrix, int k) {
    int n = matrix.length;
    PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));   // {value, row, col}
    for (int r = 0; r < Math.min(n, k); r++) heap.offer(new int[]{matrix[r][0], r, 0});
    for (int i = 1; i < k; i++) {
        int[] top = heap.poll();                     // the next smallest overall
        int r = top[1], c = top[2];
        if (c + 1 < n) heap.offer(new int[]{matrix[r][c + 1], r, c + 1});   // its row moves forward
    }
    return heap.peek()[0];
}

int kthSmallest(vector<vector<int>>& matrix, int k) {
    int n = matrix.size();
    // (value, row, col) with greater<>: a min-heap, the smallest front on top
    priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<>> heap;
    for (int r = 0; r < min(n, k); r++) heap.push({matrix[r][0], r, 0});
    for (int i = 1; i < k; i++) {
        auto [v, r, c] = heap.top();                 // the next smallest overall
        heap.pop();
        if (c + 1 < n) heap.push({matrix[r][c + 1], r, c + 1});   // its row moves forward
    }
    return get<0>(heap.top());
}

function kthSmallest(matrix, k) {
  const n = matrix.length;
  let lo = matrix[0][0], hi = matrix[n - 1][n - 1];
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    let count = 0, c = n - 1;                        // count entries <= mid, walking a staircase
    for (let r = 0; r < n; r++) {
      while (c >= 0 && matrix[r][c] > mid) c--;
      count += c + 1;
    }
    if (count >= k) hi = mid; else lo = mid + 1;     // the answer is the smallest value with count >= k
  }
  return lo;
}

def kth_smallest(matrix, k):
    n = len(matrix)
    lo, hi = matrix[0][0], matrix[n - 1][n - 1]
    while lo < hi:
        mid = (lo + hi) // 2
        count, c = 0, n - 1                         # count entries <= mid, walking a staircase
        for r in range(n):
            while c >= 0 and matrix[r][c] > mid:
                c -= 1
            count += c + 1
        if count >= k:                              # the answer is the smallest value with count >= k
            hi = mid
        else:
            lo = mid + 1
    return lo

